            self._cell = []
            self._cell_class = attrs_dict.get("class")
        elif tag == "p":
            self._paragraph = [attrs_dict.get("class"), []]
        elif tag == "style":
            self._style_parts = []
        elif tag == "a":
            self.links.append(attrs_dict.get("href"))

